// ---------------------------------------------------------------------------
// OOP Lab 05 · Inheritance. One input: N, the number of employee subtypes (2..8).
// Every number below was MEASURED by measure.py / measure_rule.py in this folder:
// the two code variants are generated by a port of the course site's own generator
// (assets/js/viz.js, VIZ["duplication"]), written to disk, counted with Python's
// tokenizer, changed, diffed at class level, and executed. See demo.json note.
// ---------------------------------------------------------------------------
const IN = {
  fields: 6,                 // the chapter's default: 6 shared fields
  added: 'salary',           // the 7th field in the chapter's own list
  names: ['Manager', 'Engineer', 'Intern', 'Designer', 'Analyst', 'Sales', 'Support', 'Director'],
  shared: ['emp_id', 'name', 'email', 'phone', 'address', 'hire_date'],
};
// measured.json -> rows[]. loc = logical lines (Python tokenizer), edits = classes whose source differs.
const IN_M = {
  2: { locDup: 16, locInh: 16, editsDup: 2, editsInh: 1 },
  3: { locDup: 24, locInh: 20, editsDup: 3, editsInh: 1 },
  4: { locDup: 32, locInh: 24, editsDup: 4, editsInh: 1 },
  5: { locDup: 40, locInh: 28, editsDup: 5, editsInh: 1 },
  6: { locDup: 48, locInh: 32, editsDup: 6, editsInh: 1 },
  7: { locDup: 56, locInh: 36, editsDup: 7, editsInh: 1 },
  8: { locDup: 64, locInh: 40, editsDup: 8, editsInh: 1 },
};
// measured.json -> rows[N].run_dup_missed_one.error (N=8, the change applied to 7 of 8 classes)
const IN_LOUD = 'TypeError: Director.__init__() takes 8 positional arguments but 9 were given';
// measured_rule.json -> rows[N].dup_missed_one: nothing raised, one class kept the raw address
const IN_QUIET = 'Boss@KMITL.AC.TH';

const inAt = (n) => IN_M[clamp(Math.round(n), 2, 8)];
const inName = (i) => IN.names[i];
// the lines engraved on one copy-paste cabinet: its own copy of every shared field
const inDupLines = (i, extraField) => {
  const f = IN.shared.concat(extraField ? [IN.added] : []);
  return ['class ' + inName(i) + ':'].concat(f.map((x) => 'self._' + x));
};
// a subtype under Employee carries only what is its own
const inSubLines = (i) => ['class ' + inName(i) + '(Employee):', 'super().__init__(**kw)', 'self._extra'];
const inBaseLines = (extraField) =>
  ['class Employee:'].concat(IN.shared.concat(extraField ? [IN.added] : []).map((x) => 'self._' + x));

// what a run of the copy-paste code finds, given how many of the N classes were edited
function inRun(n, edited, quiet) {
  const stale = Math.max(0, n - edited);
  if (!stale) return { ok: n, stale: 0, err: null, quiet: false };
  return quiet
    ? { ok: n - stale, stale, err: null, quiet: true }                 // nothing complains
    : { ok: n - stale, stale, err: IN_LOUD, quiet: false };            // it throws at the call site
}
const inVerdict = (n, edits, stale, quiet) =>
  stale === 0 ? (edits === 1 ? ['ONE PLACE', 'one edit reached all ' + n + ' subtypes', 'lime']
                             : ['ALL ' + n + ' EDITED', 'correct, but you got lucky ' + n + ' times', 'amber'])
  : quiet ? ['SILENT DRIFT', stale + ' subtype still stores ' + IN_QUIET, 'coral']
          : ['CRASH', IN_LOUD.split(':')[0] + ' at the call site', 'coral'];
